"""Offline checks using only fictional documents generated by the test."""
import csv
import importlib.util
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location('batch_parser', ROOT / 'scripts/parse_documents.py')
parser = importlib.util.module_from_spec(spec)
spec.loader.exec_module(parser)


def make_pdf(path):
    text = b'BT /F1 12 Tf 72 720 Td (Example Company raised its outlook. Demand increased this quarter.) Tj ET'
    objects = [
        b'<< /Type /Catalog /Pages 2 0 R >>',
        b'<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
        b'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>',
        b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
        b'<< /Length ' + str(len(text)).encode() + b' >>\nstream\n' + text + b'\nendstream',
    ]
    data = b'%PDF-1.4\n'
    offsets = [0]
    for i, obj in enumerate(objects, 1):
        offsets.append(len(data))
        data += f'{i} 0 obj\n'.encode() + obj + b'\nendobj\n'
    xref = len(data)
    data += b'xref\n0 6\n0000000000 65535 f \n'
    data += b''.join(f'{o:010d} 00000 n \n'.encode() for o in offsets[1:])
    data += f'trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n'.encode()
    path.write_bytes(data)


def test_pdf_to_rows_preserves_source_and_document_metadata(tmp_path):
    source = tmp_path / '2025_Q4' / 'ExamplePublisher'
    source.mkdir(parents=True)
    pdf = source / 'synthetic.pdf'
    make_pdf(pdf)
    before = pdf.read_bytes()
    output = tmp_path / 'parsed.csv'
    assert parser.parse_all_pdfs_to_single_csv(source, output)
    rows = list(csv.DictReader(output.open()))
    assert len(rows) == 2
    assert [r['Global #'] for r in rows] == ['1', '2']
    assert [r['Sentence #'] for r in rows] == ['1', '2']
    assert {r['Doc #'] for r in rows} == {'1'}
    assert {r['Year'] for r in rows} == {'2025'}
    assert {r['Quarter'] for r in rows} == {'Q4'}
    assert {r['Firm name'] for r in rows} == {'ExamplePublisher'}
    assert pdf.read_bytes() == before


def test_empty_directory_fails_without_creating_output(tmp_path):
    output = tmp_path / 'parsed.csv'
    assert not parser.parse_all_pdfs_to_single_csv(tmp_path, output)
    assert not output.exists()
